import { generateScramble as generateRandomMoveScramble } from "./scramble";

/**
 * WCA-style random-state 3x3 scrambles (the method used in competitions and cstimer),
 * generated by cubing.js in the background. cubing.js is loaded lazily and runs its
 * search in its own worker, so nothing happens on the main thread while timing.
 *
 * takeScramble() always returns immediately: a prepared random-state scramble when one
 * is ready, otherwise the old random-move scramble as a fallback (e.g. the very first
 * scramble while cubing.js is still loading).
 */

export interface TakenScramble {
  scramble: string;
  isRandomState: boolean;
}

type RandomStateGenerator = () => Promise<string>;

const QUEUE_TARGET = 2;
const queue: string[] = [];
let filling: Promise<void> | null = null;
let generator: RandomStateGenerator | null = null;
let disabled = false;

let worker: Worker | null = null;
let nextId = 0;
const pendingRequests = new Map<number, { resolve: (s: string) => void; reject: (e: Error) => void }>();

function getWorker(): Worker {
  if (worker) {
    return worker;
  }

  worker = new Worker(new URL("./scrambleWorker.ts", import.meta.url), { type: "module" });
  worker.onmessage = (event: MessageEvent<{ id: number; ok: boolean; scramble?: string; error?: string }>) => {
    const pending = pendingRequests.get(event.data.id);
    pendingRequests.delete(event.data.id);

    if (!pending) {
      return;
    }

    if (event.data.ok && event.data.scramble) {
      pending.resolve(event.data.scramble);
    } else {
      pending.reject(new Error(event.data.error ?? "scramble worker failed"));
    }
  };
  worker.onerror = (event) => {
    const error = new Error(event.message || "scramble worker error");
    pendingRequests.forEach((pending) => pending.reject(error));
    pendingRequests.clear();
  };

  return worker;
}

/** Asks the scramble worker (cubing.js inside) for one random-state scramble. */
function defaultGenerator(): Promise<string> {
  return new Promise((resolve, reject) => {
    const id = ++nextId;
    pendingRequests.set(id, { resolve, reject });
    getWorker().postMessage({ id });
  });
}

/** For tests: replace the cubing.js generator. Passing null restores the default. */
export function setRandomStateGeneratorForTests(next: RandomStateGenerator | null): void {
  generator = next;
  queue.length = 0;
  filling = null;
  disabled = false;
}

/** Keeps up to two random-state scrambles ready. Safe to call often. */
export function prefetchScrambles(): Promise<void> {
  if (disabled || filling || queue.length >= QUEUE_TARGET) {
    return filling ?? Promise.resolve();
  }

  const generate = generator ?? defaultGenerator;

  filling = (async () => {
    try {
      while (queue.length < QUEUE_TARGET) {
        const scramble = (await generate()).trim();

        if (!scramble) {
          break;
        }

        queue.push(scramble);
      }
    } catch {
      // cubing.js could not load (offline before caching, old browser): keep using
      // random-move scrambles instead of retrying forever.
      disabled = true;
    } finally {
      filling = null;
    }
  })();

  return filling;
}

/** Returns the next scramble right away and starts preparing the following one. */
export function takeScramble(): TakenScramble {
  const prepared = queue.shift();
  void prefetchScrambles();

  if (prepared) {
    return { scramble: prepared, isRandomState: true };
  }

  return { scramble: generateRandomMoveScramble(), isRandomState: false };
}

export function getPreparedScrambleCount(): number {
  return queue.length;
}
